<script>
 import {layout,inspectorMax,coverflowMax,saveLayout,resetLayout} from '../layout.svelte';
 import {onMount} from 'svelte';import {KeyRound,FolderOpen,Check,Trash2,RefreshCw} from 'lucide-svelte';import {studio,run,refresh,notify,selectProject} from '../studio.svelte';import TeamAdmin from './TeamAdmin.svelte';
 import {money} from '../cost';
 import {api,persist,isTeam} from '../api';
 let poe=$state(false),poeKey=$state('');let google=$state(false),deepseek=$state(false),googleKey=$state(''),deepseekKey=$state(''),tools=$state(null),root=$state(''),notifications=$state(typeof Notification!=='undefined'?Notification.permission:'unavailable');
 async function status(){poe=await api('poe_key_status');google=await api('credential_status');deepseek=await api('assistant_key_status');tools=await api('assistant_tools');root=studio.dataRoot;}
 onMount(()=>{status().catch(e=>studio.error=e.message);});
 async function keySet(provider){await run("正在保存密钥",async()=>{await api(provider==='google'?'credential_set':'assistant_key_set',{key:provider==='google'?googleKey:deepseekKey});googleKey='';deepseekKey='';await status();notify("密钥已保存在主机");});}
 async function remove(provider){await run("正在移除密钥",async()=>{await api(provider==='google'?'credential_delete':'assistant_key_delete');await status();notify("密钥已移除");});}
</script>
<div class="workflow-panel settings-panel"><div class="workflow-heading"><h1>设置</h1>{#if studio.settingsReturn}<button class="line-button" onclick={()=>{studio.mode=studio.settingsReturn;studio.settingsReturn='';}}>返回 {studio.settingsReturn==='assistant'?"处理图片":"生成图片"}</button>{/if}</div><div class="settings-grid">{#if !isTeam}<TeamAdmin/><section class="settings-block"><h2>API 连接</h2><label>Google API 密钥<span class:connected={google}>{google?"已连接":"未配置"}</span><div class="input-action"><input type="password" autocomplete="off" aria-label="Google API 密钥" bind:value={googleKey} placeholder="输入 API 密钥"/><button disabled={!googleKey||!!studio.busy} onclick={()=>keySet('google')}>保存密钥</button></div></label><div class="button-row"><button class="line-button" disabled={!google||!!studio.busy} onclick={()=>run("正在检查连接",async()=>{await api('credential_test');notify("Google 连接正常");})}>检查连接</button><button disabled={!google||!!studio.busy} aria-label="移除 Google 密钥" onclick={()=>remove('google')}><Trash2 size={15}/></button></div><label>DeepSeek API 密钥<span class:connected={deepseek}>{deepseek?"已连接":"未配置"}</span><div class="input-action"><input type="password" autocomplete="off" aria-label="DeepSeek API 密钥" bind:value={deepseekKey} placeholder="输入 API 密钥"/><button disabled={!deepseekKey||!!studio.busy} onclick={()=>keySet('deepseek')}>保存密钥</button></div></label><button class="line-button" disabled={!deepseek||!!studio.busy} onclick={()=>remove('deepseek')}>移除 DeepSeek 密钥</button><label>Poe API 密钥<span>{poe?'已连接':'未配置'}</span><div class="input-action"><input type="password" bind:value={poeKey} autocomplete="off" placeholder="输入 Poe API 密钥"/><button disabled={!poeKey||!!studio.busy} onclick={()=>run('保存 Poe 密钥',async()=>{await api('poe_key_set',{key:poeKey});poeKey='';await status();})}>保存</button></div></label><button disabled={!poe||!!studio.busy} onclick={()=>run('移除 Poe 密钥',async()=>{await api('poe_key_delete');await status();})}>移除 Poe 密钥</button><p class="hint">密钥保存在主机的 Windows 凭据管理器中。</p></section>{:else}<section class="settings-block"><h2>API 连接</h2><p>API 由主机提供，无需在此配置。</p></section>{/if}
<section class="settings-block"><h2>工作区</h2>{#if studio.projectWarnings.length}<div role="alert"><h3>需要检查的项目</h3><p>这些项目未能加载，原文件仍保留。请从备份恢复项目文件，或选择其他数据目录。</p>{#each studio.projectWarnings as warning}<p class="field-error project-warning-detail">{warning}</p>{/each}</div>{/if}<div class="field-grid"><label>右侧面板宽度（像素）<input aria-label="右侧面板宽度（像素）" type="number" min="220" max={inspectorMax()} value={Math.min(layout.inspectorWidth,inspectorMax())} onchange={e=>{layout.inspectorWidth=Math.min(inspectorMax(),Math.max(220,Number(e.target.value)||280));saveLayout();}}/></label><label>图片浏览区高度（像素）<input aria-label="图片浏览区高度（像素）" type="number" min="100" max={coverflowMax()} value={Math.min(layout.coverflowHeight,coverflowMax())} onchange={e=>{layout.coverflowHeight=Math.min(coverflowMax(),Math.max(100,Number(e.target.value)||144));saveLayout();}}/></label></div><button class="text-button" onclick={resetLayout}>恢复默认布局</button>{#if !isTeam}<label>主机数据目录<div class="input-action"><input aria-label="主机数据目录" bind:value={root}/><button aria-label="选择数据目录" onclick={()=>run("正在选择文件夹",async()=>{const path=await api('pick_output');if(path)root=path;})}><FolderOpen size={16}/></button></div></label><button class="line-button" disabled={!root||root===studio.dataRoot||!!studio.busy} onclick={()=>run("正在切换工作区",async()=>{await api('data_root_switch',{path:root});studio.pid='';studio.aid='';studio.drafts={};studio.selected=[];await refresh();notify("工作区已切换");})}>使用此目录</button>{/if}<label>画布<select bind:value={studio.background} onchange={()=>persist('background',studio.background)}><option value="paper">浅色</option><option value="checker">透明网格</option><option value="dark">深色</option></select></label><label>桌面通知<button class="line-button" disabled={notifications==='granted'||notifications==='unavailable'} onclick={async()=>notifications=await Notification.requestPermission()}>{notifications==='granted'?"已启用":"启用通知"}</button></label><label>预览加速<select aria-label="预览加速" bind:value={studio.gpuPreviewEnabled} onchange={()=>persist('gpu-preview-enabled',studio.gpuPreviewEnabled)}><option value={true}>优先使用显卡</option><option value={false}>兼容模式</option></select></label><div class="status-line"><span>当前预览方式</span><b>{studio.previewEngine==='gpu'?"显卡加速已就绪":studio.previewEngine==='cpu'?'CPU':"正在检查"}</b></div><h3>本地处理工具</h3><div class="status-line"><span>图像处理引擎</span><b class="connected">就绪</b></div><div class="status-line"><span>OpenCV</span><b>{tools?(tools.available?"就绪":"不可用"):"正在检查"}</b></div>{#if tools&&!tools.available}<p class="hint">{tools.error||tools.message||"降噪工具不可用，请联系主机管理员检查 OpenCV。"}</p>{/if}</section>
<section class="settings-block"><h2>费用</h2><div class="field-grid"><label>显示币种<select bind:value={studio.currency} onchange={()=>persist('currency',studio.currency)}><option value="CNY">人民币（CNY）</option><option value="USD">美元（USD）</option></select></label><label>USD → CNY<input type="number" min=".01" step=".01" bind:value={studio.exchangeRate} onchange={()=>persist('exchangeRate',studio.exchangeRate)}/></label></div><div class="model-table">{#each studio.catalog?.models||[] as model}<div><b>{model.name}</b><small>{model.id}</small><span>{model.resolutions.join(' / ')}</span><span>{model.imageUsd?.['1K']!=null?`${money(model.imageUsd['1K'],studio.currency,studio.exchangeRate)} / 1K`:"费用未知"}</span></div>{/each}</div><p class="hint">此处为估算费用，实际费用以供应商账单为准。</p></section>
<section class="settings-block"><h2>快捷键</h2>{#each [['Ctrl + S',"保存版本"],['Ctrl + Z',"撤销"],['Ctrl + Shift + Z',"重做"],['Ctrl + 1–4',"切换功能页面"],['Q / E',"切换编辑工具"],['← / →',"上一张／下一张图片"],['Ctrl + wheel',"缩放"],['0',"适配并居中"],['\\',"按住查看原图"],["鼠标右键","工具菜单"]] as [key,label]}<div class="shortcut"><span>{label}</span><kbd>{key}</kbd></div>{/each}</section></div></div>
